-- Buyer sign-in on our own database (Better Auth 1.7), replacing Supabase Auth.
-- Columns follow the Better Auth core schema (generated by @better-auth/cli,
-- 5 Nov 2026), mapped to snake_case. Additive only: nothing existing changes.
-- Applied by scripts/auth/apply-better-auth-tables.ts (dev, then live on a yes).

CREATE TABLE IF NOT EXISTS "auth_user" (
  "id"             TEXT PRIMARY KEY,
  "name"           TEXT NOT NULL,
  "email"          TEXT NOT NULL,
  "email_verified" BOOLEAN NOT NULL DEFAULT false,
  "image"          TEXT,
  "created_at"     TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at"     TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS "auth_user_email_key" ON "auth_user"("email");

CREATE TABLE IF NOT EXISTS "auth_session" (
  "id"         TEXT PRIMARY KEY,
  "expires_at" TIMESTAMP(3) NOT NULL,
  "token"      TEXT NOT NULL,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "ip_address" TEXT,
  "user_agent" TEXT,
  "user_id"    TEXT NOT NULL REFERENCES "auth_user"("id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "auth_session_token_key" ON "auth_session"("token");
CREATE INDEX IF NOT EXISTS "auth_session_user_id_idx" ON "auth_session"("user_id");

CREATE TABLE IF NOT EXISTS "auth_account" (
  "id"                       TEXT PRIMARY KEY,
  "account_id"               TEXT NOT NULL,
  "provider_id"              TEXT NOT NULL,
  "user_id"                  TEXT NOT NULL REFERENCES "auth_user"("id") ON DELETE CASCADE,
  "access_token"             TEXT,
  "refresh_token"            TEXT,
  "id_token"                 TEXT,
  "access_token_expires_at"  TIMESTAMP(3),
  "refresh_token_expires_at" TIMESTAMP(3),
  "scope"                    TEXT,
  "password"                 TEXT,
  "created_at"               TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at"               TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "auth_account_user_id_idx" ON "auth_account"("user_id");

CREATE TABLE IF NOT EXISTS "auth_verification" (
  "id"         TEXT PRIMARY KEY,
  "identifier" TEXT NOT NULL,
  "value"      TEXT NOT NULL,
  "expires_at" TIMESTAMP(3) NOT NULL,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "auth_verification_identifier_idx" ON "auth_verification"("identifier");
